transaction:
BEGIN;
SET LOCAL lock_timeout = '5s';
LOCK TABLE supabase_migrations.schema_migrations IN SHARE ROW EXCLUSIVE MODE;
DO $alias$
DECLARE inserted_count integer;
BEGIN
  IF (SELECT count(*) FROM supabase_migrations.schema_migrations) <> 288
     OR (SELECT md5(string_agg(to_jsonb(m)::text,E'\n' ORDER BY version)) FROM supabase_migrations.schema_migrations m) IS DISTINCT FROM '85207590d258a138d1aa2f16657b8fdc'
  THEN RAISE EXCEPTION 'Migration history changed since verified 288-row baseline'; END IF;
  IF EXISTS (SELECT 1 FROM supabase_migrations.schema_migrations WHERE version IN ('20261118100000','20261119090000','20261120090000','20261121090000','20261122090000'))
  THEN RAISE EXCEPTION 'Canonical alias already exists; stop without retry'; END IF;
  IF (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version='20260916155430' AND name='sp_international_passport_foundation' AND cardinality(statements)=1 AND encode(sha256(convert_to(statements[1],'UTF8')),'hex')='89a6d170bea44f57f28fd63be7e9e7219de0bfb0f26f1ef8cf65bc03f1103a7c') <> 1 THEN RAISE EXCEPTION 'Hosted mapping mismatch: 20261118100000'; END IF;
  IF (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version='20260916155456' AND name='sp_international_credential_wallet' AND cardinality(statements)=1 AND encode(sha256(convert_to(statements[1],'UTF8')),'hex')='c9870a981d8e743fcada8eae8e1695fb6362e26db913f2895576cb7c5544f651') <> 1 THEN RAISE EXCEPTION 'Hosted mapping mismatch: 20261119090000'; END IF;
  IF (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version='20260916155521' AND name='sp_credential_selective_sharing_v2' AND cardinality(statements)=1 AND encode(sha256(convert_to(statements[1],'UTF8')),'hex')='717c8119a4f32b484db92af6e1c9b5a621387d90142768413d7108c3c152d817') <> 1 THEN RAISE EXCEPTION 'Hosted mapping mismatch: 20261120090000'; END IF;
  IF (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version='20260916155551' AND name='sp_closed_credential_catalogue' AND cardinality(statements)=1 AND encode(sha256(convert_to(statements[1],'UTF8')),'hex')='b22d3fa2955d42583e113f2ab8fc0d70c47f9448c0f6f0d5dc99596eb35a3785') <> 1 THEN RAISE EXCEPTION 'Hosted mapping mismatch: 20261121090000'; END IF;
  IF (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version='20260916155620' AND name='cv_owned_application_snapshot' AND cardinality(statements)=1 AND encode(sha256(convert_to(statements[1],'UTF8')),'hex')='b5bd06661fef9dd5266ab362553a68d77583b8a4c8fd5fdc430a5a21c8139936') <> 1 THEN RAISE EXCEPTION 'Hosted mapping mismatch: 20261122090000'; END IF;
  INSERT INTO supabase_migrations.schema_migrations (version,name)
  VALUES ('20261118100000','sp_international_passport_foundation'),
    ('20261119090000','sp_international_credential_wallet'),
    ('20261120090000','sp_credential_selective_sharing_v2'),
    ('20261121090000','sp_closed_credential_catalogue'),
    ('20261122090000','cv_owned_application_snapshot')
  ON CONFLICT (version) DO NOTHING;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  IF inserted_count <> 5 OR (SELECT count(*) FROM supabase_migrations.schema_migrations) <> 293
  THEN RAISE EXCEPTION 'Expected exactly five alias rows and 293 total rows'; END IF;
END
$alias$;
COMMIT;
